const { readProject } = require('../../projectReader')
const { merge, sort } = require('../../merge')
const { srv4, mtxSidecar4 } = require('../../registries/mta')
const mvn = require('../../mvn')
const cds = require('../../../cds')
const { read, write, exists, mkdirp, path: { join, dirname } } = cds.utils

// Keep custom policies below the DCL root; cds build regenerates ams/dcl/cap/.
const EXTENSION_DEVELOPER_DCL = join('ams', 'dcl', 'extensibility', 'extensionDeveloper.dcl')

const SIDECAR_PACKAGE_JSON = join('mtx', 'sidecar', 'package.json')

module.exports = class AmsTemplate extends require('../../plugin') {

    static help() {
        return 'authorization via AMS'
    }

    requires() {
        return ['ias']
    }

    static hasInProduction(env) {
        const { dependencies, devDependencies } = readProject()
        return env.requires?.auth?.ams || devDependencies?.['@sap/ams-dev'] || devDependencies?.['@sap/ams'] || dependencies?.['@sap/ams']
    }

    async run() {
        const project = readProject()
        await merge(__dirname, 'files/package.json.hbs').into('package.json', { project, forceOverwrite: true })
        project.isNodejs && await sort('package.json', 'dependencies')
        await sort('package.json', 'devDependencies')
        if (project.isJava) await mvn.add('ams')
        // The sidecar's cds.ExtensionDeveloper role needs a custom DCL policy.
        if (project.hasExtensibility && !exists(EXTENSION_DEVELOPER_DCL)) {
            const template = await read(join(__dirname, 'files', 'extensionDeveloper.dcl'), 'utf-8')
            await mkdirp(dirname(EXTENSION_DEVELOPER_DCL))
            await write(EXTENSION_DEVELOPER_DCL, template)
        }
        if (project.isNodejs && exists(SIDECAR_PACKAGE_JSON)) {
            await merge(__dirname, 'files/sidecar.package.json.hbs').into(SIDECAR_PACKAGE_JSON, { project })
            await sort(SIDECAR_PACKAGE_JSON, 'dependencies')
        }
    }

    async combine(facet) {
        const project = readProject(facet)
        const { affected } = project

        if (affected('mta')) {
            const additions = [
                srv4(project.srv.path),
                { in: 'modules', where: { name: `${project.appName}-ams-policies-deployer` } }
            ]
            if (project.hasMultitenancy) {
                additions.push(mtxSidecar4(project.isJava ? 'mtx/sidecar' : 'gen/mtx/sidecar'))
            }
            await merge(__dirname, 'files/mta.yaml.hbs').into('mta.yaml', { project, additions })
        }

        if (affected('cf-manifest')) {
            const amsPoliciesDeployer = {
                in: 'applications',
                where: { name: `${project.appName}-ams-policies-deployer` }
            }
            await merge(__dirname, 'files/manifest.yml.hbs').into('manifest.yml', { project, additions: [amsPoliciesDeployer] })
        }

        if (affected('kyma')) {
            const chartDependency = { in: 'dependencies', where: { alias: 'ams-policies-deployer' } }
            const containerModule = { in: 'modules', where: { name: `${project.appName}-ams-policies-deployer` } }
            await Promise.all([
                merge(__dirname, 'files/Chart.yaml.hbs').into('chart/Chart.yaml', { project, additions: [chartDependency] }),
                merge(__dirname, 'files/values.yaml.hbs').into('chart/values.yaml', { project }),
                merge(__dirname, 'files/containerize.yaml.hbs').into('containerize.yaml', { project, additions: [containerModule] })
            ])
        }
    }
}
